cat > /app/output/styles.css <<'CSS'
:root {
  --bg: oklch(21% 0.02 274);
  --bg-elev: oklch(26% 0.02 274);
  --bg-soft: oklch(30% 0.02 274);
  --text: oklch(94% 0.01 274);
  --muted: oklch(72% 0.03 274);
  --line: oklch(38% 0.02 274);
  --brand: oklch(64% 0.15 232);
  --brand-soft: oklch(52% 0.11 232);
  --gain: oklch(75% 0.18 145);
  --loss: oklch(66% 0.2 25);
  --warn: oklch(77% 0.14 83);
  --shadow: 0 10px 30px rgb(0 0 0 / 0.35);
}
* { box-sizing: border-box; }
html,body { margin:0; padding:0; background:var(--bg); color:var(--text); font-family: Inter, "DM Sans", system-ui, -apple-system, Segoe UI, Roboto, sans-serif; }
a { color:inherit; text-decoration:none; }
.shell { min-height:100vh; display:grid; grid-template-columns: 240px 1fr; }
.sidebar { border-right:1px solid var(--line); background: linear-gradient(180deg, var(--bg-elev), var(--bg)); padding:18px 14px; position:sticky; top:0; height:100vh; }
.brand { display:flex; align-items:center; gap:10px; font-weight:700; letter-spacing:.3px; margin-bottom:20px; }
.logo { width:28px; height:28px; border-radius:8px; background:linear-gradient(135deg,var(--brand),oklch(74% 0.12 180)); box-shadow:var(--shadow); }
.nav { display:flex; flex-direction:column; gap:6px; }
.nav a { padding:10px 12px; border-radius:10px; color:var(--muted); font-weight:600; font-size:14px; }
.nav a.active, .nav a:hover { background:var(--bg-soft); color:var(--text); }
.main { padding:14px; }
.topbar { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:12px; }
.search { flex:1; max-width:480px; background:var(--bg-elev); border:1px solid var(--line); color:var(--text); border-radius:10px; padding:10px 12px; }
.badges { display:flex; gap:8px; }
.badge { padding:6px 10px; border-radius:999px; font-size:12px; border:1px solid var(--line); color:var(--muted); background:var(--bg-elev); }
.grid { display:grid; gap:12px; }
.grid-2 { grid-template-columns: 1.5fr 1fr; }
.grid-3 { grid-template-columns: repeat(3,minmax(0,1fr)); }
.card { background:var(--bg-elev); border:1px solid var(--line); border-radius:14px; padding:12px; box-shadow: var(--shadow); }
.card h3 { margin:0 0 10px; font-size:14px; color:var(--muted); text-transform:uppercase; letter-spacing:.6px; }
.kv { display:flex; justify-content:space-between; align-items:center; padding:7px 0; border-bottom:1px dashed color-mix(in oklab, var(--line), transparent 50%); font-size:13px; }
.kv:last-child { border-bottom:0; }
.price { font-weight:700; font-size:20px; }
.gain { color:var(--gain); }
.loss { color:var(--loss); }
.tabs { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px; }
.tab { border:1px solid var(--line); background:var(--bg-soft); color:var(--muted); border-radius:9px; padding:7px 10px; font-size:12px; cursor:pointer; }
.tab.active { background:color-mix(in oklab, var(--brand-soft), black 28%); color:white; border-color:color-mix(in oklab, var(--brand), black 35%); }
.table { width:100%; border-collapse:collapse; font-size:13px; }
.table th,.table td{ padding:8px 6px; border-bottom:1px solid color-mix(in oklab, var(--line), transparent 45%); text-align:left; }
.table th { color:var(--muted); font-size:12px; text-transform:uppercase; letter-spacing:.4px; }
.spark { height:44px; border-radius:8px; background: linear-gradient(180deg, color-mix(in oklab, var(--brand), transparent 70%), transparent), repeating-linear-gradient(90deg, color-mix(in oklab, var(--line), transparent 65%) 0 1px, transparent 1px 24px); position:relative; overflow:hidden; }
.spark::after { content:""; position:absolute; inset:9px 8px; background: linear-gradient(120deg, transparent 0 10%, color-mix(in oklab,var(--brand),white 10%) 10% 14%, transparent 14% 30%, color-mix(in oklab,var(--gain),white 5%) 30% 35%, transparent 35% 55%, color-mix(in oklab,var(--loss),white 5%) 55% 58%, transparent 58% 100%); opacity:.9; }
.hero-row { display:grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap:10px; }
.metric { background:var(--bg-elev); border:1px solid var(--line); border-radius:12px; padding:10px; }
.metric .name { font-size:12px; color:var(--muted); }
.metric .val { font-size:18px; font-weight:700; margin-top:5px; }
.chart-shell { display:grid; grid-template-columns: 300px 1fr 320px; gap:10px; }
.watch-head { display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; }
.accordion h4 { margin:8px 0; font-size:12px; color:var(--muted); text-transform:uppercase; }
.accordion[data-collapsed="true"] table { display:none; }
.term-canvas { min-height:520px; border:1px solid var(--line); border-radius:12px; background: radial-gradient(circle at 20% 10%, color-mix(in oklab,var(--brand),transparent 85%), transparent 45%), linear-gradient(180deg, color-mix(in oklab,var(--bg-soft), black 15%), var(--bg)); position:relative; overflow:hidden; }
.candle { position:absolute; width:8px; border-radius:2px; }
.toolbar { display:flex; justify-content:space-between; margin-bottom:8px; gap:8px; flex-wrap:wrap; }
.small { font-size:12px; color:var(--muted); }
.toggle { width:42px; height:24px; border-radius:999px; border:1px solid var(--line); position:relative; background:var(--bg-soft); cursor:pointer; }
.toggle::after{ content:""; width:18px; height:18px; border-radius:50%; background:white; position:absolute; top:2px; left:2px; transition:.2s; }
.toggle.on { background:color-mix(in oklab,var(--brand),black 40%); }
.toggle.on::after { left:21px; }
@media (max-width: 1200px){ .chart-shell{ grid-template-columns:1fr; } .hero-row{ grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media (max-width: 900px){ .shell{ grid-template-columns:1fr; } .sidebar{ position:relative; height:auto; } .grid-2,.grid-3,.hero-row{ grid-template-columns:1fr; } }
